303	    /**
304	     * Title-case a value by upper-casing the first letter of every
305	     * whitespace-separated word and lower-casing the remaining letters, while
306	     * preserving the original whitespace. A {@code null} value stays
307	     * {@code null}.
308	     */
309	    private static String toTitleCase(String value) {
310	        if (value == null) {
311	            return null;
312	        }
313	        StringBuilder result = new StringBuilder(value.length());
314	        boolean startOfWord = true;
315	        for (int i = 0; i < value.length(); i++) {
316	            char c = value.charAt(i);
317	            if (Character.isWhitespace(c)) {
318	                startOfWord = true;
319	                result.append(c);
320	            } else if (startOfWord) {
321	                result.append(Character.toTitleCase(Character.toLowerCase(c)));
322	                startOfWord = false;
323	            } else {
324	                result.append(Character.toLowerCase(c));
325	            }
326	        }
327	        return result.toString();
328	    }
329	
330	    /**
331	     * The maximum number of owners that may be registered on any single day (by registration date).
332	     */
333	    private static final int MAX_OWNERS_PER_DAY = 20;
334	
335	    /**
336	     * Determine whether the daily registration limit has already been reached for the day the given
337	     * owner is being registered on. Counts the existing owners whose registration date matches the new
338	     * owner's registration date and returns {@code true} once that count has reached
339	     * {@link #MAX_OWNERS_PER_DAY}.
340	     */
341	    private boolean isDailyRegistrationLimitReached(Owner owner) {
342	        LocalDate registrationDate = owner.getRegistrationDate();
343	        if (registrationDate == null) {
344	            return false;
345	        }
346	        long registeredToday = ownerRepository.findAll().stream()
347	            .filter(existing -> !existing.getId().equals(owner.getId()))
348	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
349	            .count();
350	        return registeredToday >= MAX_OWNERS_PER_DAY;
351	    }
352	
353	    /**
354	     * The maximum number of owners that may be registered in any single city (compared case-insensitively).
355	     */
356	    private static final int MAX_OWNERS_PER_CITY = 8;
357	
358	    /**
359	     * Determine whether the given owner's city has already reached its capacity. Counts the existing owners
360	     * whose city matches the new owner's city (compared case-insensitively) and returns {@code true} once
361	     * that count has reached {@link #MAX_OWNERS_PER_CITY}. An owner without a city is never at capacity.
362	     */
363	    private boolean isCityCapacityReached(Owner owner) {
364	        String city = owner.getCity();
365	        if (city == null) {
366	            return false;
367	        }
368	        long ownersInCity = ownerRepository.findAll().stream()
369	            .filter(existing -> !existing.getId().equals(owner.getId()))
370	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
371	            .count();
372	        return ownersInCity >= MAX_OWNERS_PER_CITY;
373	    }
374	
375	    private boolean isDuplicateTelephone(Owner owner) {
376	        String telephone = normalizeTelephone(owner.getTelephone());
377	        return ownerRepository.findAll().stream()
378	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
379	                && Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
380	    }
381	
382	    /**
383	     * Normalize a telephone number for duplicate detection by stripping every
384	     * character that is not a digit (spaces, dashes and parentheses), so that
385	     * "(613) 555-0100" and "6135550100" are treated as the same number. A
386	     * {@code null} value stays {@code null}.
387	     */
388	    private static String normalizeTelephone(String value) {
389	        if (value == null) {
390	            return null;
391	        }
392	        return value.replaceAll("[^0-9]", "");
393	    }
394	
395	    private boolean isDuplicateEmail(Owner owner) {
396	        String email = owner.getEmail();
397	        if (email == null || email.isBlank()) {
398	            return false;
399	        }
